-- 1) insertedby null records  - update security user id
select sp.application, sp.supportno, sp.jiraenv, sp.jirarequestno, sp.jirarequestsent, 
		sp.ldssregion, sp.frommailid, sp.insertedby, sp.updatedby, sp.updatedon  
		, (select up.securityusersid 
				   FROM muser m
					 JOIN userprofile up ON m.securityusersid::text = up.securityusersid::text 
						 -- AND m.activeflag = 1 
						 -- AND up.activeflag = 1
					 JOIN teammemberassignment tma ON tma.securityusersid::text = up.securityusersid::text -- AND tma.activeflag = 1
					 JOIN teammember tm ON tm.teammemberid = tma.teammemberid -- AND tm.activeflag = 1
					 JOIN team t ON t.teamid = tm.teamid -- AND tm.activeflag = 1
					 join county on county.countyid = t.countyid::uuid
				where up.email  = sp.frommailid 
				order by tma.insertedon  desc
				limit 1
		  ) as new_insertedby
from defecttracking.supportlog sp
where ( sp.insertedby is null or btrim(sp.insertedby) = '' )
	and sp.activeflag = 1 ;
	
