					 JOIN team t ON t.teamid = tm.teamid -- AND tm.activeflag = 1
					 join county on county.countyid = t.countyid::uuid
				where up.email = sp.frommailid 
				order by tma.insertedon  desc
				limit 1
				),
	updatedby = 'CIDM-7244-1',
	updatedon = now()
where ( insertedby is null or btrim(insertedby) = '' )
	and activeflag = 1 ;	
	
	
