-- 3) cjams is not null and apporval status is not Apporved  - update atstus as Apporved 
select sp.application, sp.supportno, sp.jiraenv, sp.jirarequestno, sp.jirarequestsent, 
		sp.ldssregion, sp.frommailid, sp.insertedby, sp.updatedby, sp.updatedon  
from defecttracking.supportlog sp
where ( sp.jirarequestno is not null or btrim(sp.jirarequestno) <> '' )
	and ( sp.jirarequestsent is null or btrim(sp.jirarequestsent) = '')
	and sp.activeflag = 1 
	and coalesce(jirarequestsent, 'Pending') not in ( 'Approve', 'Approved') ;

update defecttracking.supportlog sp
set jirarequestsent = 'Approved', 
	updatedby = 'CIDM-7244-3',
	updatedon = now()
where ( jirarequestno is not null or btrim(jirarequestno) <> '' )
	and ( jirarequestsent is null or btrim(jirarequestsent) = '')
	and activeflag = 1 
	and coalesce(jirarequestsent, 'Pending') not in ( 'Approve', 'Approved') ;


